/* ==========================================================================
   🐍 PYTHON ALTERNATIVE / البديل البرمجي بلغة بايثون لنفس المهمة
   --------------------------------------------------------------------------
   This node is documented in both Python and JavaScript.
   Below is the production-grade Python function equivalent:

def guardrails_safety_filter(input_data: dict) -> dict:
    """
    فلتر الأمان لكشف محاولات الـ Prompt Injection والمدخلات الضارة.

    Enterprise guardrails that detect prompt injection attempts in both
    Arabic and English before the message reaches the LLM.

    Args:
        input_data: Normalized ingress data with sanitized_message.

    Returns:
        Input data augmented with guardrail_safe and flagged_reason.
    """
    raw_msg = input_data.get("sanitized_message") or input_data.get(
        "customer_message", "Hello"
    )

    injection_patterns = [
        r"ignore\s+(all\s+)?(previous|prior|above)\s+instructions",
        r"system\s*prompt",
        r"jailbreak",
        r"bypass\s+rules",
        r"disregard\s+guidelines",
    ]

    prompt_injection = False
    for pattern in injection_patterns:
        if re.search(pattern, raw_msg, re.IGNORECASE):
            prompt_injection = True
            break

    return {
        **input_data,
        "guardrail_safe": not prompt_injection,
        "flagged_reason": "prompt_injection_attempt" if prompt_injection else None,
    }


# ==============================================================================
# 4. WORKFLOW 03 — Build Prompt Payload
# Node: "Build Prompt Payload"
# Purpose: Constructs the structured LLM prompt with FAQ context, conversation
#          history, and strict response-format instructions. If guardrails
#          flagged the input, returns a deflection immediately.
# ==============================================================================
   ========================================================================== */

/* === ACTIVE JAVASCRIPT IMPLEMENTATION === */
const input = $input.first()?.json || {};
const rawMsg = input.sanitized_message || input.customer_message || 'Hello';

// Enterprise Guardrails: Detect Prompt Injection and Harmful Input
const injectionPatterns = [
  /ignore\s+(all\s+)?(previous|prior|above)\s+instructions/i,
  /system\s*prompt/i,
  /jailbreak/i,
  /bypass\s+rules/i,
  /disregard\s+guidelines/i
];

let promptInjection = false;
for (const pattern of injectionPatterns) {
  if (pattern.test(rawMsg)) {
    promptInjection = true;
    break;
  }
}

return [{
  json: {
    ...input,
    guardrail_safe: !promptInjection,
    flagged_reason: promptInjection ? 'prompt_injection_attempt' : null
  }
}];

const item = $input.first()?.json || {};
const customerMsg = item.sanitized_message || item.customer_message || 'Hello';
const locale = item.locale || (customerMsg.match(/[؀-ۿ]/) ? 'ar' : 'en');
const history = (item.conversation_history || []).slice(-3).map(h => h.sender_type + ': ' + h.content).join('\n');
const msg = customerMsg.toLowerCase();

// === KEYWORD PRE-CLASSIFIER (reliable for Arabic + English) ===
const escalationKeywords = [
  'شكوى', 'مشكلة', 'ضايق', 'زعلان', 'غاضب', 'سيء', 'سء', 'موظف', 'ممثل', 'مدير',
  'كلمني حد', 'تحكي مع', 'complaint', 'frustrated', 'angry', 'terrible', 'worst',
  'agent', 'manager', 'representative', 'human', 'speak to', 'talk to', 'escalate'
];
const orderKeywords = [
  'تتبع', 'حالة طلب', 'طلب خدمة', 'رقم طلب', 'رقم التتبع', 'شحنة', 'معاملة'
];
const faqKeywords = [
  'شروط', 'تقديم', 'تسجيل', 'تخصص', 'تخصصات', 'مسار', 'مسارات', 'امتحان', 'دراسة', 'شهادة', 'منح', 'منحة',
  'رسوم', 'مؤهل', 'seb', 'lms', 'إنسحاب', 'انسحاب', 'admission', 'requirement', 'requirements', 'course',
  'program', 'apply', 'registration', 'scholarship', 'track', 'tracks', 'specialization', 'specializations', 'certificate', 'study',
  'exam', 'eligible', 'eligibility', 'document', 'fee', 'cost', 'debi', 'depi', 'رواد', 'مصر الرقمية',
  'مبادرة', 'المبادرة', 'تفاصيل', 'معلومات', 'نبذة', 'عن المبادرة', 'برنامج', 'دورات', 'تدريب',
  'digilians', 'الرواد الرقميون'
];

let keywordIntent = null;
let offTopicReply = '';
const isOutOfScope = /\bweather\b|\bforecast\b|\b(?:football|soccer) match\b|\bwho won\b.{0,35}\b(?:match|game|football|soccer)\b|\b(?:write|create|generate)\s+(?:me\s+)?(?:a\s+)?(?:python|javascript|java|c\+\+|sql)\s+(?:script|code|program)\b|\bwrite me a python script\b|الطقس|درجة الحرارة|توقعات الطقس|مباراة كرة القدم|من فاز.{0,30}(?:مباراة|كرة)|اكتب\s*لي\s*(?:سكربت|كود|برنامج)/i.test(customerMsg);
const hasExplicitOrderSemantics = /\b(?:order|orders|service request|shipment|tracking number|tracking code)\b|\btrack(?:ing)?\b.{0,40}\b(?:order|shipment|service request)\b|\b(?:order|shipment|service request)\b.{0,40}\b(?:track|tracking|status)\b|\b(?:ORD|SRV)-\d+\b/i.test(customerMsg) || orderKeywords.some(kw => msg.includes(kw));

if (escalationKeywords.some(kw => msg.includes(kw))) {
  keywordIntent = 'human_escalation';
} else if (isOutOfScope) {
  keywordIntent = 'general_support';
  offTopicReply = locale === 'ar'
    ? 'عذراً، يختص هذا المساعد حصرياً بالمعلومات والخدمات الرسمية لمبادرة رواد مصر الرقمية (DEPI)، لذلك هذا الموضوع يقع خارج نطاق اختصاص المساعد.'
    : 'Sorry, this assistant is specialized exclusively in the Digital Egypt Pioneers Initiative (DEPI) and this topic is outside our scope.';
} else if (hasExplicitOrderSemantics) {
  keywordIntent = 'order_lookup';
} else if (faqKeywords.some(kw => msg.includes(kw))) {
  keywordIntent = 'faq_query';
}

// If keyword classifier matched, bypass LLM entirely
if (keywordIntent) {
  return [{
    json: {
      direct_bypass: true,
      ai_output: {
        intent: keywordIntent,
        confidence: 0.9,
        entities: keywordIntent === 'order_lookup' ? { order_number: (customerMsg.match(/SRV-\d+|ORD-\d+/i) || [null])[0] } : {},
        sentiment: 'neutral',
        requires_human: keywordIntent === 'human_escalation',
        direct_response: offTopicReply
      },
      customer_message: customerMsg,
      locale: locale,
      customer: item.customer,
      conversation: item.conversation,
      conversation_history: item.conversation_history || [],
      channel: item.channel,
      channel_user_id: item.channel_user_id
    }
  }];
}

// === LLM FALLBACK (only for ambiguous messages) ===
const promptText = 'Classify this customer message into ONE intent for the Digital Egypt Pioneers Initiative (DEPI) customer service. Reply ONLY with valid JSON.\n\n' +
  'Intents:\n' +
  '- faq_query: Questions about DEPI programs, admission, tracks, specializations, registration, exams, or other initiatives\n' +
  '- order_lookup: Asking about order/service status or tracking number\n' +
  '- human_escalation: Angry customer, complaint, wants human agent\n' +
  '- general_support: Greetings, thanks, small talk\n\n' +
  'Examples:\n' +
  'Message: Hello -> {\"intent\":\"general_support\",\"confidence\":1.0}\n' +
  'Message: What are the DEPI tracks -> {\"intent\":\"faq_query\",\"confidence\":0.95}\n' +
  'Message: I want to complain -> {\"intent\":\"human_escalation\",\"confidence\":0.95}\n\n' +
  'Response format: {\"intent\":\"...\",\"confidence\":0.9,\"entities\":{},\"sentiment\":\"positive|neutral|frustrated\",\"requires_human\":false,\"direct_response\":\"\"}\n\n' +
  (history ? 'Previous conversation:\n' + history + '\n\n' : '') +
  'Customer message: ' + JSON.stringify(customerMsg);

return [{
  json: {
    ollama_body: {
      model: 'qwen2.5:1.5b', keep_alive: '10m',
      prompt: promptText,
      stream: false,
      options: { temperature: 0.1, num_predict: 200, num_ctx: 2048 }
    },
    locale: locale,
    customer_message: customerMsg,
    conversation_history: item.conversation_history || [],
    customer: item.customer,
    conversation: item.conversation,
    channel: item.channel,
    channel_user_id: item.channel_user_id,
    guardrail_safe: item.guardrail_safe !== false,
    use_llm: true
  }
}];

const nodeInput = $input.first()?.json || {};
const buildData = $('Build Prompt Payload').first()?.json || {};

if (buildData.direct_bypass) {
  return [{
    json: {
      ai_output: buildData.ai_output,
      customer_message: buildData.customer_message,
      customer: buildData.customer,
      conversation: buildData.conversation,
      channel: buildData.channel,
      channel_user_id: buildData.channel_user_id,
      conversation_history: buildData.conversation_history || [],
      locale: buildData.locale
    }
  }];
}

const rawResponse = nodeInput.response;
const originalMsg = (buildData.customer_message || '').toLowerCase();
const locale = buildData.locale || 'ar';
const isAr = locale === 'ar';

let parsed = null;
try {
  if (rawResponse) {
    let cleanJson = rawResponse.replace(/```json/gi, '').replace(/```/g, '').trim();
    const match = cleanJson.match(/\{[\s\S]*\}/);
    if (match) cleanJson = match[0];
    parsed = JSON.parse(cleanJson);
  }
} catch (e) {
  parsed = null;
}

// Enterprise Heuristic Fail-Safe
if (!parsed || !parsed.intent) {
  const isOrder = originalMsg.includes('order') || originalMsg.includes('srv-') || originalMsg.includes('ord-') || originalMsg.includes('طلب') || originalMsg.includes('شحن') || originalMsg.includes('تتبع');
  const isEscalation = originalMsg.includes('human') || originalMsg.includes('supervisor') || originalMsg.includes('angry') || originalMsg.includes('complaint') || originalMsg.includes('frustrated') || originalMsg.includes('speak to') || originalMsg.includes('talk to') || originalMsg.includes('representative') || originalMsg.includes('manager') || originalMsg.includes('موظف') || originalMsg.includes('مشرف') || originalMsg.includes('شكوى') || originalMsg.includes('إنسان') || originalMsg.includes('متضايق');
  const isFaq = originalMsg.includes('skill') || originalMsg.includes('admission') || originalMsg.includes('requirement') || originalMsg.includes('course') || originalMsg.includes('program') || originalMsg.includes('apply') || originalMsg.includes('registration') || originalMsg.includes('scholarship') || originalMsg.includes('track') || originalMsg.includes('certificate') || originalMsg.includes('study') || originalMsg.includes('exam') || originalMsg.includes('eligib') || originalMsg.includes('document') || originalMsg.includes('شروط') || originalMsg.includes('تقديم') || originalMsg.includes('خدمات') || originalMsg.includes('رواد') || originalMsg.includes('مصر الرقمية') || originalMsg.includes('depi') || originalMsg.includes('debi') || originalMsg.includes('مسار') || originalMsg.includes('تخصص') || originalMsg.includes('تسجيل') || originalMsg.includes('امتحان') || originalMsg.includes('seb') || originalMsg.includes('شهادة') || originalMsg.includes('مزايا') || originalMsg.includes('منحة');

  if (isEscalation) {
    parsed = {
      intent: 'human_escalation',
      confidence: 0.95,
      entities: {},
      sentiment: 'frustrated',
      requires_human: true,
      direct_response: isAr ? 'يتم الآن تحويلك إلى ممثل خدمة العملاء المختص لمساعدتك...' : 'Connecting you with a human support specialist...'
    };
  } else if (isOrder) {
    const match = originalMsg.match(/(?:ord|srv)-\d+/i);
    parsed = {
      intent: 'order_lookup',
      confidence: 0.90,
      entities: { order_number: match ? match[0].toUpperCase() : 'SRV-1001' },
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري الاستعلام عن بيانات ومسار شحنتك/طلبك...' : 'Looking up your service request details...'
    };
  } else if (isFaq) {
    parsed = {
      intent: 'faq_query',
      confidence: 0.90,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr ? 'جاري البحث في قاعدة المعرفة المعتمدة لمبادرة رواد مصر الرقمية (DEPI)...' : 'Searching the official DEPI knowledge base...'
    };
  } else {
    parsed = {
      intent: 'general_support',
      confidence: 0.85,
      entities: {},
      sentiment: 'neutral',
      requires_human: false,
      direct_response: isAr
        ? 'أهلاً وسهلاً بك في منصة خدمة العملاء لمبادرة رواد مصر الرقمية (DEPI). كيف يمكننا مساعدتك اليوم؟'
        : 'Welcome to the Digital Egypt Pioneers Initiative (DEPI) Customer Service platform. How may we assist you today?'
    };
  }
}

// Preserve obvious FAQ intent if Ollama times out or returns an over-broad greeting.
const faqSignals = ["admission", "requirement", "program", "course", "apply", "application", "registration", "scholarship", "track", "tracks", "certificate", "study", "exam", "eligible", "eligibility", "depi", "debi", "digilians", "initiative", "pioneers", "شروط", "تقديم", "رواد", "مصر الرقمية", "الرواد الرقميون", "مبادرة", "المبادرة", "مسار", "مسارات", "منح", "منحة", "تخصص", "تخصصات", "اونلاين", "أونلاين"];
if (parsed.intent === "general_support" && faqSignals.some(term => originalMsg.includes(term))) {
  parsed.intent = "faq_query";
  parsed.confidence = Math.max(parsed.confidence || 0, 0.9);
  parsed.requires_human = false;
}

if (!parsed.entities) { parsed.entities = {}; }
if (!parsed.entities.order_number) {
  const match = originalMsg.match(/(?:ord|srv)-\d+/i);
  if (match) { parsed.entities.order_number = match[0].toUpperCase(); }
}

return [{
  json: {
    ai_output: parsed,
    customer_message: buildData.customer_message,
    customer: buildData.customer,
    conversation: buildData.conversation,
    channel: buildData.channel,
    channel_user_id: buildData.channel_user_id,
    conversation_history: buildData.conversation_history || [],
    locale: locale,
    classifier_status: nodeInput.error ? "fallback_after_error" : "model_response"
  }
}];
